import{_ as i,a0 as d,w as l,s as n,I as a,x as p,a1 as r,A as o,ao as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"apt remove 和 apt purge: 有什么区别？ | LCTT x X-CMD","titleTemplate":false,"description":"apt remove 和 apt purge: 有什么区别？ | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"apt remove 和 apt purge: 有什么区别？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"apt remove 和 apt purge: 有什么区别？ | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20221123.0 ⭐️⭐️ apt remove vs apt purge What’s the Difference","title":"apt remove 和 apt purge: 有什么区别？","tag":"202301","desc":""},"relativePath":"202301/20221123.0 ⭐️⭐️ apt remove vs apt purge What’s the Difference.md","filePath":"[post].md"}'),m={name:"202301/20221123.0 ⭐️⭐️ apt remove vs apt purge What’s the Difference.md"};function g(u,e,f,c,h,v){const t=d("Link");return l(),n("div",null,[e[21]||(e[21]=a("h1",{id:"apt-remove-和-apt-purge-有什么区别",tabindex:"-1"},[p("apt remove 和 apt purge: 有什么区别？ "),a("a",{class:"header-anchor",href:"#apt-remove-和-apt-purge-有什么区别","aria-label":"Permalink to “apt remove 和 apt purge: 有什么区别？”"},"​")],-1)),e[22]||(e[22]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202301/19/113744ucqk6f69t4hbi8h8.jpg",alt:""})],-1)),a("p",null,[e[1]||(e[1]=p("如果你想 ",-1)),r(t,{href:"https://itsfoss.com/apt-remove/"},{default:o(()=>[...e[0]||(e[0]=[p("在 Ubuntu 上使用终端卸载软件",-1)])]),_:1}),e[2]||(e[2]=p("，可以使用：",-1))]),e[23]||(e[23]=s('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt remove package_name</span></span></code></pre></div><p>但是在很多论坛，你可能会看到别人说，如果你想彻底删除软件就用 <code>apt purge</code>。</p><p>你可能会觉得很困惑，因为 <code>apt purge</code> 和 <code>apt remove</code> 看起来是一样的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt purge package_name</span></span></code></pre></div><p>为什么会有两个如此像的命令来删除软件包呢？两者之间有什么不同呢？下面将为你揭晓。</p><h3 id="apt-remove-和-apt-purge-有什么不同" tabindex="-1">apt-remove 和 apt-purge 有什么不同？ <a class="header-anchor" href="#apt-remove-和-apt-purge-有什么不同" aria-label="Permalink to “apt-remove 和 apt-purge 有什么不同？”">​</a></h3><p><code>apt-remove</code> 和 <code>apt-purge</code> 的相同之处就是都可以卸载软件包，但是运行 <code>apt-purge</code> 除了可以删除安装包之外，还可以清除相关的配置文件。这是两者之间唯一的不同点。要注意的是这两条命令都不能删除用户主目录中相关的应用程序文件。</p><p>你是否遇到过这样的情况，卸载一个软件然后重新安装，却发现之前的设置都还在。这是因为用 <code>apt remove</code> 不能删除该软件的相关配置文件。</p><h4 id="哪些东西被删除了-哪些还在" tabindex="-1">哪些东西被删除了？哪些还在？ <a class="header-anchor" href="#哪些东西被删除了-哪些还在" aria-label="Permalink to “哪些东西被删除了？哪些还在？”">​</a></h4><p>我分享一个使用 <code>apt remove</code> 和 <code>apt purge</code> 两个命令分别卸载 mplayer 这个软件的实际例子。重点是看每次操作后还残余哪些文件。</p><p>这是删除前的文件：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/mplayer-before-removal.png" alt="mplayer before removal"></p><p>现在运行 <code>apt remove</code> 这个命令：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/apt-uninstall-package-ubuntu.png" alt="apt uninstall package ubuntu"></p><p>下面的是还残留在系统中的文件：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/files-after-mplayer-removal.png" alt="files after mplayer removal"></p><p>我们可以看到，有两个地方残留着 mplayer 的文件: <code>/etc</code> 和 <code>/home/abhishek</code>。</p><p>这次我们重新安装 mplayer，然后用 <code>apt purge</code> 来卸载软件。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/apt-purge-command.png" alt="apt purge command"></p><p>现在让我们看看与 mplayer 相关的文件：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/files-after-apt-purge.png" alt="files after mplayer removal"></p><p>我们可以看到 <code>/etc</code> 目录下的文件已经没有了。</p><p>但是在主目录中的文件呢？<code>apt purge</code> 会删除它们吗？</p><p>答案是否定的。<code>apt</code> 命令不会删除主目录中的配置文件。所以它们仍然在系统中，除非你手动删除。但是这些文件所占的空间真的很小，几乎不占磁盘空间。</p><p>值得注意的是，不是所有的软件在主目录或者 <code>/etc</code> 目录下都有配置文件。</p><h4 id="使用-apt-remove-或者-apt-purge-的效果" tabindex="-1">使用 apt remove 或者 apt purge 的效果 <a class="header-anchor" href="#使用-apt-remove-或者-apt-purge-的效果" aria-label="Permalink to “使用 apt remove 或者 apt purge 的效果”">​</a></h4>',26)),a("p",null,[e[4]||(e[4]=p("我能想到的一个实际例子就是 Discord，你用 deb 文件 ",-1)),r(t,{href:"https://itsfoss.com/install-discord-linux/"},{default:o(()=>[...e[3]||(e[3]=[p("在 Ubuntu 上安装了 Discord",-1)])]),_:1}),e[5]||(e[5]=p("。然后登录自己的账号，之后又卸载并重新用 deb 文件安装。",-1))]),e[24]||(e[24]=s('<p>现在如果你打开 Discord，你会发现你的账号自动登录了。是不是觉得很奇怪？</p><p>这是个功能，像一些软件，比如 Discord、VirtualBox，它们会提供更新，就是卸载现在的版本然后下载新的（尽管你不知道它内部怎么进行的），但是它在卸载的时候，这些软件的配置文件没有被删除，所以等你打开这些软件的时候就会自动登录。</p><p>当你想卸载一个软件，但是想保留你过去使用该软件留下的配置文件的时候，你就可以用 <code>apt remove</code>。</p><p>但是，有时候用它不能满足你的需求，比如当你没有配置好一个软件的时候，你想要重新开始，这个时候用 <code>apt purge</code> 就比较合适。</p><h4 id="运行-apt-purge-是否可以用通配符删除" tabindex="-1">运行 apt purge 是否可以用通配符删除？ <a class="header-anchor" href="#运行-apt-purge-是否可以用通配符删除" aria-label="Permalink to “运行 apt purge 是否可以用通配符删除？”">​</a></h4><p>当你删除一个包的时候，它会提示 <code>removing package-name*</code>。这意味着它会删除以这个包名开头的所有文件。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/apt-purge-wild-card.png" alt="apt purge wild card"></p><p>我在手册页之类的文档中没有找到关于这个问题的答案。所以我自己做了一个小测试，我安装了 espeak 和 espeak-ng 这两个软件，espeak* 应该可以通配扩展到 espeak-ng。</p><p>但是当我用 <code>apt purge</code> 删除 espeak 包时，espeak-ng 包还在，没有被一并删除。因此，这似乎是有一种防止通配符的扩展的机制。</p><h3 id="那么-你应该使用-apt-remove-还是-apt-purge-呢" tabindex="-1">那么，你应该使用 apt remove 还是 apt purge 呢？ <a class="header-anchor" href="#那么-你应该使用-apt-remove-还是-apt-purge-呢" aria-label="Permalink to “那么，你应该使用 apt remove 还是 apt purge 呢？”">​</a></h3><p>很少有人会一直使用 <code>apt purge</code>。</p><p>在我看来，一般清况下，用 <code>apt remove</code> 就可以了，但是当你想删除那些自定义配置文件时，你就得用 <code>apt purge</code>。</p><p>不管是用 <code>apt remove</code> 还是 <code>apt purge</code>，你都需要从用户的主目录中删除残余的配置文件，并运行 <code>apt autoremove</code> 来清除任何依赖的包。</p><p>现在到你啦。你现在对 <code>apt remove</code> 和 <code>apt purge</code> 的区别更加了解吗？你更喜欢使用哪一个呢？</p><hr>',15)),a("p",null,[e[7]||(e[7]=p("via: ",-1)),r(t,{href:"https://itsfoss.com/apt-remove/"},{default:o(()=>[...e[6]||(e[6]=[p("https://itsfoss.com/apt-remove/",-1)])]),_:1})]),a("p",null,[e[12]||(e[12]=p("作者：",-1)),r(t,{href:"https://itsfoss.com/"},{default:o(()=>[...e[8]||(e[8]=[p("Abhishek Prakash",-1)])]),_:1}),e[13]||(e[13]=p(" 选题：",-1)),r(t,{href:"https://github.com/lkxed"},{default:o(()=>[...e[9]||(e[9]=[p("lkxed",-1)])]),_:1}),e[14]||(e[14]=p(" 译者：",-1)),r(t,{href:"https://github.com/Tingze-G"},{default:o(()=>[...e[10]||(e[10]=[p("Tingze-G",-1)])]),_:1}),e[15]||(e[15]=p(" 校对：",-1)),r(t,{href:"https://github.com/wxy"},{default:o(()=>[...e[11]||(e[11]=[p("wxy",-1)])]),_:1})]),a("p",null,[e[18]||(e[18]=p("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[16]||(e[16]=[p("LCTT",-1)])]),_:1}),e[19]||(e[19]=p(" 原创编译，",-1)),r(t,{href:"https://linux.cn/"},{default:o(()=>[...e[17]||(e[17]=[p("Linux中国",-1)])]),_:1}),e[20]||(e[20]=p(" 荣誉推出",-1))])])}const x=i(m,[["render",g]]);export{T as __pageData,x as default};
